const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={name:'Bloom & Root',industry:'Home & lifestyle',description:'An independent plant shop helping people create greener homes with easy-care indoor plants and friendly advice.',audience:'First-time plant owners and busy apartment dwellers',offer:'A personalised plant starter bundle',goal:'Product purchase',tone:'Warm & helpful',campaign:'A greener home starts here'};
let state;try{state=JSON.parse(localStorage.getItem('orbit-v1'))}catch{}state=state||{brief:defaults,campaign:null,leads:[],edits:{}};let view='Overview',blogIndex=0,lpStage=0,answers={},leadResult=false;

const demoSets=[
 {name:'Bloom & Root',label:'Plant shop',icon:'✿',brief:{...defaults},personas:[
 {role:'Maya · The first-time plant parent',need:'A small, low-maintenance plant suited to her low-light apartment and a care routine she understands.',question:'Which plant suits my room, and how will I know when to water it?',objection:'She has lost plants before and worries that “easy care” will still be too difficult.'},
 {role:'Daniel · The busy home-office owner',need:'A greener workspace without adding daily maintenance to an already full schedule.',question:'What can thrive near my desk with just a few minutes of care each week?',objection:'He does not want complicated equipment, a large collection or an ongoing commitment.'},
 {role:'Priya · The thoughtful gift buyer',need:'A plant gift that fits the recipient’s home, with clear instructions and an appealing presentation.',question:'How do I choose a gift when I do not know the light in their home?',objection:'She worries about choosing something impractical that becomes a burden.'}]},
 {name:'Bright Path Academy',label:'Education',icon:'⌘',brief:{name:'Bright Path Academy',industry:'Education & training',description:'An independent adult learning provider offering practical online language classes with small groups and flexible evening schedules.',audience:'Working adults exploring language learning for everyday confidence, career opportunities or personal goals',offer:'An introductory language class and learning-path consultation',goal:'Enrolment',tone:'Warm & helpful',campaign:'Find your next learning chapter'},personas:[
 {role:'Alex · The career-focused learner',need:'Practical language skills that fit around work, with clear milestones and opportunities to practise.',question:'Will these lessons help me handle real workplace conversations?',objection:'Alex is unsure whether the course will focus on relevant practice or general theory.'},
 {role:'Sam · The returning learner',need:'A supportive way to restart learning without feeling embarrassed about forgotten basics.',question:'Can I start at my actual level without being left behind?',objection:'Past classroom experiences made Sam reluctant to speak in front of a group.'},
 {role:'Robin · The schedule-conscious planner',need:'Transparent class times, realistic study expectations and a course that fits a changing weekly routine.',question:'How much time do I need outside class, and what happens if I miss a session?',objection:'Robin is reluctant to commit before understanding attendance and catch-up options.'}]},
 {name:'Flowdesk',label:'Software',icon:'◈',brief:{name:'Flowdesk',industry:'Software & technology',description:'A workflow software business helping small service teams organise client requests, track handoffs and reduce repeated manual data entry.',audience:'Small service-business owners, operations managers and team leads',offer:'A guided workflow demo and trial workspace',goal:'Start a trial',tone:'Clear & professional',campaign:'Make room for better work'},personas:[
 {role:'Jordan · The hands-on operator',need:'A clearer view of incoming requests without juggling several spreadsheets and inboxes.',question:'Can this help me track work without creating more admin?',objection:'Jordan worries that setting up a new system will take longer than the current workaround.'},
 {role:'Casey · The team champion',need:'An approachable workflow that colleagues will actually adopt, with clear responsibilities and handoffs.',question:'How can I test this with one team before asking everyone to switch?',objection:'Casey has seen earlier tools fail because the team found them confusing.'},
 {role:'Morgan · The budget owner',need:'A clear understanding of scope, costs, implementation and measurable operational value.',question:'What would a useful trial prove before we commit?',objection:'Morgan wants evidence of fit and a complete cost picture before approving another subscription.'}]}
];
function demoLibrary(){return intro('DEMO PERSONA LIBRARY','Meet your starting audience.','Nine fictional examples. Load a business to explore its connected campaign.')+demoSets.map((d,j)=>`<div class="section-head"><div><h2>${esc(d.name)}</h2><span class="small">${esc(d.label)} · Fictional demonstration business</span></div><button class="primary" data-demo="${j}">Use this demo campaign →</button></div><div class="grid">${d.personas.map((p,i)=>`<div class="card"><div class="avatar">${d.icon}</div><span class="badge">DEMO PERSONA 0${i+1}</span><h3>${esc(p.role)}</h3><b class="small">WHAT THEY NEED</b><p>${esc(p.need)}</p><b class="small">THE QUESTION THEY ASK</b><p>${esc(p.question)}</p><b class="small">WHAT HOLDS THEM BACK</b><p>${esc(p.objection)}</p></div>`).join('')}</div>`).join('')+'<div class="notice">Demo personas illustrate how the app works. Validate your own personas with interviews, customer feedback and business data.</div>';}
function loadDemo(index){if(state.campaign&&!confirm('Load this demo campaign? Your current draft assets and edits will be replaced. Export first if you want to keep them.'))return;const d=demoSets[index];state.brief={...d.brief};generate();state.campaign.personas=d.personas.map(p=>({...p}));state.campaign.source='Fictional demo';persist();view='Personas';render();toast(d.name+' demo loaded.');}
async function requestGeneration(form){
 const data=Object.fromEntries(new FormData(form)),mode=data.generationMode;delete data.generationMode;
 const oldBrief=state.brief;state.brief=data;
 if(mode!=='ai'){generate();return;}
 if(!['http:','https:'].includes(location.protocol)){state.brief=oldBrief;toast('AI mode needs the Vercel-hosted app. Use Demo mode in this downloaded file.');return;}
 const button=form.querySelector('[type="submit"]');button.disabled=true;button.textContent='Creating your AI campaign…';
 try{const response=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({brief:data}),signal:AbortSignal.timeout(120000)});let result;try{result=await response.json()}catch{throw new Error('AI endpoint unavailable. Deploy the full Vercel source, or use Demo mode.');}if(!response.ok)throw new Error(result.error||'AI generation failed.');const c=result.campaign;if(!c||!Array.isArray(c.personas)||c.personas.length!==3||!Array.isArray(c.blogs)||c.blogs.length!==3)throw new Error('Invalid AI campaign response.');
 state.campaign={...c,roles:c.personas.map(p=>p.role),source:'Gemini draft',created:new Date().toISOString()};state.edits={};c.blogs.forEach((a,i)=>{state.edits['blogbody'+i]=a.body;state.edits['adhead'+i]=a.searchHeadline;state.edits['adbody'+i]=a.searchBody;state.edits['social'+i]=a.socialBody;state.edits['lphead'+i]=a.landingHeadline;});state.edits['magnet-title']=c.magnet;state.edits['magnet-body']=c.resource;state.edits.followup=c.followup;answers={};persist();view='Overview';render();toast('AI campaign created. Review all draft content before publishing.');
 }catch(error){state.brief=oldBrief;const msg=error.name==='TimeoutError'?'Generation timed out. Your previous campaign is unchanged.':error.message;let box=form.querySelector('.generation-error');if(!box){box=document.createElement('div');box.className='generation-error notice';box.setAttribute('role','alert');form.appendChild(box);}box.textContent=msg;
 }finally{if(button.isConnected){button.disabled=false;button.textContent='Create my campaign →';}}
}
function personalisedResource(){return (state.edits['magnet-body']||resourceText()).replace(/\{\{answer([012])\}\}/g,(_,i)=>answers[i]||'Add your answer');}

const navs=[['Overview','◈'],['Business brief','⌘'],['Personas','♧'],['Demo personas','✿'],['Blog studio','☷'],['Ad studio','↗'],['Landing pages','▤'],['Lead magnet','✧'],['Leads & insights','◎']];
function persist(){try{localStorage.setItem('orbit-v1',JSON.stringify(state))}catch{toast('Storage unavailable. Export your campaign to keep your work.')}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function profile(b){let t=(b.industry+' '+b.description).toLowerCase();if(/plant|garden/.test(t))return {subject:'indoor plants',outcome:'a greener home',pain:'keeping plants alive with limited time and light',criteria:['Light in your space','Time for care','Room and available space'],tips:['Map the natural light in your room before choosing a plant.','Choose a care routine you can maintain every week.','Start with one suitable plant and observe it before expanding.'],tool:'Plant-fit finder',magnet:'Your room-by-room plant starter plan',roles:['The first-time plant parent','The busy apartment dweller','The thoughtful gift buyer']};if(/education|school|course|training/.test(t))return {subject:'learning options',outcome:'the right learning path',pain:'choosing a programme with the right fit and support',criteria:['Learning goals','Schedule and format','Support needed'],tips:['Write down the outcome you want from the programme.','Compare the schedule, teaching format and support available.','Ask for a sample session and confirm the full commitment.'],tool:'Learning-path finder',magnet:'Your learning-path comparison workbook',roles:['The careful researcher','The time-conscious learner','The outcome-focused decision maker']};if(/software|saas|technology/.test(t))return {subject:'workflow tools',outcome:'a smoother working day',pain:'manual work and uncertainty about switching tools',criteria:['Biggest workflow bottleneck','Team size and adoption','Integration requirements'],tips:['Document one recurring workflow and its current steps.','Identify where work gets delayed or entered twice.','Test one improvement with a small team before rolling it out.'],tool:'Workflow readiness check',magnet:'Your workflow improvement roadmap',roles:['The hands-on operator','The team champion','The budget owner']};if(/service|consult|agency|professional/.test(t))return {subject:'service providers',outcome:'a clearer plan of action',pain:'knowing which support is worth the investment',criteria:['Your immediate priority','Scope and timing','Support required'],tips:['Define the outcome and what success would look like.','Separate must-have support from work you can handle internally.','Ask potential providers about scope, process and next steps.'],tool:'Priority assessment',magnet:'Your priorities and provider-selection workbook',roles:['The independent researcher','The overwhelmed owner','The ready-to-act buyer']};if(/home|renovat|construction/.test(t))return {subject:'home improvement options',outcome:'a home that works for you',pain:'unclear scope, timing and project costs',criteria:['Project priority','Timing and disruption','Scope and budget range'],tips:['List the problem your project needs to solve.','Separate essential work from optional upgrades.','Compare written scopes and confirm who manages each stage.'],tool:'Project readiness check',magnet:'Your project planning workbook',roles:['The early-stage explorer','The practical planner','The ready-to-start homeowner']};return {subject:b.offer||'available options',outcome:'a choice that fits your needs',pain:'comparing options and knowing where to start',criteria:['Your main priority','Your timeframe','The support you need'],tips:[`Define what you want to achieve with ${b.offer||'your purchase'}.`,'List your must-haves and the trade-offs you can accept.','Compare the details, support and next steps before committing.'],tool:'Find-your-fit assessment',magnet:'Your personalised decision workbook',roles:['The curious explorer','The careful comparer','The ready-to-act buyer']};}
function generate(){answers={};const b=state.brief,p=profile(b);state.edits={};state.campaign={...p,created:new Date().toISOString(),source:'Template draft',personas:p.roles.map((role,i)=>({role,need:[`Understand ${p.subject} without feeling overwhelmed.`,`Find a practical solution to ${p.pain}.`,`Feel confident that ${b.offer} meets their needs.`][i],question:[`Where should I start with ${p.subject}?`,`How do I compare the options that fit my situation?`,`What is included, and what happens next?`][i],objection:['Too much information and unfamiliar terminology.','Unclear fit, time commitment and hidden trade-offs.','Unanswered questions about the offer and support.'][i]})),blogs:[{stage:'Awareness',title:`How to get started with ${p.subject}: a practical guide`,cta:`Try the ${p.tool.toLowerCase()}`},{stage:'Consideration',title:`How to compare ${p.subject} for your needs`,cta:`Build ${p.magnet.toLowerCase()}`},{stage:'Decision',title:`Is ${b.offer} right for you? Questions to ask before deciding`,cta:action()}]};persist();view='Overview';render();toast('Campaign created. Review and edit your draft assets.');}
function action(){return ({'Product purchase':'Explore the offer','Book a consultation':'Request a consultation','Request a quote':'Request a quote','Start a trial':'Explore a trial','Enrolment':'Ask about enrolment'})[state.brief.goal]||'Take the next step'}
function ed(key,value,tag='div'){return `<${tag} class="editable" contenteditable="true" role="textbox" aria-label="Edit ${esc(key)}" data-edit="${esc(key)}">${esc(state.edits[key]??value)}</${tag}>`}
function intro(k,title,sub,button=''){return `<div class="intro"><div><div class="eyebrow">${k}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${button}</div>`}function go(v){view=v;render();window.scrollTo(0,0)}
function render(){const b=state.brief,c=state.campaign;$('#nav').innerHTML=navs.map(([n,i])=>`<button data-nav="${n}" class="${view===n?'active':''}"><em>${i}</em>${n}</button>`).join('');$('#crumb').textContent=view;let html='';if(view==='Business brief'){html=intro('01 / THE FOUNDATION','Start with your business.','A clear brief makes every campaign asset more relevant.')+`<div class="notice">Need inspiration? <button data-go="Demo personas">Explore nine demo personas →</button></div><form id="brief" class="card"><div class="formgrid">${field('name','Business name')}${select('industry','Industry',['Home & lifestyle','Education & training','Software & technology','Professional services','Ecommerce & retail','Health & wellbeing','Food & hospitality','Other / custom'])}${field('description','What does your business do?','textarea','full')}${field('audience','Who do you want to reach?','textarea')}${field('offer','What are you promoting?','textarea')}${select('goal','Primary conversion',['Product purchase','Book a consultation','Request a quote','Start a trial','Enrolment'])}${select('tone','Brand tone',['Warm & helpful','Clear & professional','Bold & energetic'])}${field('campaign','Campaign name','input','full')}<label class="full">Generation mode<select name="generationMode"><option value="ai">Gemini — generate a tailored AI campaign</option><option value="demo">Demo — local templates</option></select></label></div><div class="notice">Personas are hypotheses, not customer research. AI mode sends this business brief to Gemini through the server; it does not send your stored leads. Live research, email delivery and CRM integrations are not included.</div><div class="actions"><button class="primary" type="submit">${c?'Rebuild':'Create'} my campaign →</button><button type="button" id="sample">Try the plant shop example</button></div><p class="small">Rebuilding replaces draft assets and edits. Existing demo leads are retained.</p></form>`}
else if(view==='Demo personas'){html=demoLibrary()}
else if(!c){html=intro('YOUR NEXT GREAT CAMPAIGN','From business idea to connected journey.','Create the personas, content and pages that move people forward.')+hero()+`<div class="section-head"><h2>Everything starts with one brief</h2></div><div class="grid">${[['01','Understand your audience','Draft three personas around needs, questions and objections.'],['02','Build the whole journey','Connect organic blogs, ads and three landing pages.'],['03','Give value. Earn interest.','Create a useful resource with a working lead-capture demo.']].map(a=>`<div class="card"><span class="badge">${a[0]}</span><h3>${a[1]}</h3><p>${a[2]}</p></div>`).join('')}</div>`}
else if(view==='Overview'){html=intro('CAMPAIGN WORKSPACE',b.campaign||b.name,`${b.name} · ${b.industry} · ${c.source||'Template draft'}`,`<button data-go="Business brief">Edit business brief ↗</button>`)+hero()+`<div class="section-head"><h2>Your campaign, connected</h2><small>3 stages · 1 continuous journey</small></div><div class="grid">${['Awareness','Consideration','Decision'].map((s,i)=>`<div class="card"><div class="stage-icon">${['◎','✧','↗'][i]}</div><span class="number">0${i+1} / ${['ATTRACT','ENGAGE','CONVERT'][i]}</span><h3>${['Help them discover','Give them a useful plan','Make the next step easy'][i]}</h3><p>${[c.tool,c.magnet,b.offer][i]}</p><div class="card-foot"><span>Blog + ad + landing page</span><button data-preview="${i}">Preview ↗</button></div></div>`).join('')}</div><div class="two"><div class="card"><span class="eyebrow">THE CUSTOMER JOURNEY</span><div class="flow"><div><b>Find their fit</b><small>Assessment</small></div><span>→</span><div><b>Save their plan</b><small>Value exchange</small></div><span>→</span><div><b>Take action</b><small>${esc(b.goal)}</small></div></div><p class="small">Close the flywheel with a helpful check-in, feedback and a reason to return.</p></div><div class="card"><span class="eyebrow">YOUR ASSET LIBRARY</span><div class="flow"><div><b>3</b><small>Personas</small></div><div><b>3</b><small>Blog drafts</small></div><div><b>6</b><small>Ad drafts</small></div><div><b>1</b><small>Lead magnet</small></div></div><button data-go="Landing pages">Explore your landing pages →</button></div></div>`}
else if(view==='Personas'){html=intro('02 / THE PEOPLE','Start with what matters to them.','Editable audience hypotheses to validate through customer research.',`<button data-go="Demo personas">Explore demo personas →</button>`)+`<div class="grid">${c.personas.map((p,i)=>`<div class="card"><div class="avatar">${['◔','◑','◕'][i]}</div><span class="badge">PERSONA 0${i+1}</span>${ed('persona'+i,p.role,'h3')}<p class="small">Potential segment within: ${esc(b.audience)}</p><b class="small">WHAT THEY NEED</b>${ed('need'+i,p.need,'p')}<b class="small">THE QUESTION THEY ASK</b>${ed('question'+i,p.question,'p')}<b class="small">WHAT HOLDS THEM BACK</b>${ed('objection'+i,p.objection,'p')}</div>`).join('')}</div><div class="notice">Click any draft text to edit it. Changes save on this device. Avoid assigning a persona from an ad click alone; use declared preferences to refine it.</div>`}
else if(view==='Blog studio'){let a=c.blogs[blogIndex];html=intro('03 / ORGANIC DISCOVERY','Useful answers. A natural next step.','Three editable starter articles mapped to customer intent.')+`<div class="tabs">${c.blogs.map((a,i)=>`<button data-blog="${i}" class="${i===blogIndex?'active':''}">${a.stage}</button>`).join('')}</div><div class="card article"><span class="badge">${a.stage.toUpperCase()} · EDITORIAL DRAFT</span>${ed('blogtitle'+blogIndex,a.title,'h2')}${ed('blogbody'+blogIndex,blogBody(blogIndex),'div')}<div class="notice">Publishing checklist: add original expertise, verified product details, relevant sources and internal links. This draft is not researched or optimised against live search data.</div><button data-preview="${blogIndex}">${esc(a.cta)} →</button></div>`}
else if(view==='Ad studio'){html=intro('04 / PAID DISCOVERY','The right message at the right moment.','Editable search and social copy. Drafts only; no ads are published.')+`<div class="grid">${c.blogs.map((a,i)=>`<div class="card"><span class="badge">${a.stage.toUpperCase()}</span><h3>Search ad</h3>${ed('adhead'+i,[`Find your fit with ${b.name}`,`Get your practical planning guide`,`${b.offer} | ${b.name}`][i],'h3')}${ed('adbody'+i,[`Not sure where to start with ${c.subject}? Explore your priorities with our free ${c.tool.toLowerCase()}.`,`Turn your priorities into a useful plan. Create ${c.magnet.toLowerCase()} and save a copy.`,`See what ${b.offer} includes. Get clear answers and choose your next step with ${b.name}.`][i],'p')}<div class="card-foot">Destination: ${a.stage} page <button data-preview="${i}">View ↗</button></div></div><div class="card"><span class="badge orange">${a.stage.toUpperCase()}</span><h3>Social ad</h3>${ed('social'+i,[`${b.tone==='Bold & energetic'?'Ready for your next move.':b.tone==='Clear & professional'?'Make an informed choice.':'A little clarity goes a long way.'}\nIf you're exploring ${c.subject}, start with what matters to you. Our ${c.tool.toLowerCase()} helps you choose a direction—before you commit.`,`Less guesswork. A plan you can actually use.\nGet ${c.magnet.toLowerCase()}, shaped around your priorities. Preview it first, then save your copy.`,`Ready for the next step?\nExplore ${b.offer} from ${b.name}. Check the fit, ask your questions and move forward when you're ready.`][i],'p')}<div class="card-foot">CTA: ${['Try the assessment','Build my plan',action()][i]}</div></div>`).join('')}</div><div class="notice">Check platform character limits, targeting rules and factual claims before publishing. No prices, endorsements or results have been invented.</div>`}
else if(view==='Landing pages'){html=intro('05 / CONNECTED EXPERIENCES','Three pages. One thoughtful journey.','Preview as a customer: assess your needs, get a resource, then explore the offer.')+`<div class="grid">${c.blogs.map((a,i)=>`<div class="card"><div class="preview-mini"><span class="small">${esc(b.name)}</span><b>${['Find what fits you.','Your next step, mapped.','Move forward with clarity.'][i]}</b><div class="line"></div><div class="dot"></div></div><p class="eyebrow">0${i+1} / ${a.stage}</p><h3>${esc([c.tool,c.magnet,b.offer][i])}</h3><p>${['A short interactive assessment with immediate results.','A personalised workbook unlocked through a demo email form.','Offer details, honest FAQs and an enquiry form.'][i]}</p><button class="primary" data-preview="${i}">Open page ↗</button></div>`).join('')}</div><div class="notice">The preview pages share assessment answers. Contact forms store demo leads on this device; they do not send email or connect to a CRM.</div><div class="card"><h3>Landing-page headlines</h3>${[0,1,2].map(i=>`<label>${c.blogs[i].stage}</label>${ed('lphead'+i,head(i),'h3')}`).join('')}</div>`}
else if(view==='Lead magnet'){html=intro('06 / THE VALUE EXCHANGE','Give them something worth keeping.','A useful, editable workbook connected to the customer’s priorities.',`<button class="primary" id="download">Download resource ↓</button>`)+`<div class="two"><div class="card"><span class="badge">PERSONALISED WORKBOOK</span>${ed('magnet-title',c.magnet,'h2')}<p>Designed for ${esc(b.audience)}.</p>${ed('magnet-body',resourceText(),'div')}<div class="actions"><button data-preview="1">Test the value exchange ↗</button></div></div><div class="card"><h3>What makes the exchange useful?</h3><ul class="bullet"><li>Immediate assessment results before asking for contact details.</li><li>A visible resource preview so people know what they receive.</li><li>A plan that includes their assessment choices.</li><li>An actual downloadable text workbook.</li><li>Optional marketing consent, separate from the resource request.</li></ul><div class="notice">Prototype delivery: download in the browser. Email delivery and secure return links require a backend integration.</div><h3>After conversion: keep the flywheel moving</h3>${ed('followup',`1. Deliver the resource and explain one practical first step.\n2. Follow up with a helpful answer to a common question.\n3. For marketing subscribers, introduce ${b.offer} when relevant.\n4. After purchase or service delivery, ask for feedback and offer a useful next resource.`,'p')}</div></div>`}
else if(view==='Leads & insights'){html=intro('07 / LEARN & IMPROVE','See the interest you’re earning.','Local demo records from your landing-page preview.')+`<div class="grid"><div class="card"><span class="small">Resource requests</span><h1>${state.leads.filter(l=>l.type==='Resource').length}</h1></div><div class="card"><span class="small">Enquiries</span><h1>${state.leads.filter(l=>l.type==='Enquiry').length}</h1></div><div class="card"><span class="small">Marketing opt-ins</span><h1>${state.leads.filter(l=>l.consent).length}</h1></div></div><div class="card" style="margin-top:20px;overflow:auto"><table class="table"><thead><tr><th>Email</th><th>Business</th><th>Action</th><th>Marketing consent</th><th>Date</th></tr></thead><tbody>${state.leads.length?state.leads.map(l=>`<tr><td>${esc(l.email)}</td><td>${esc(l.business||b.name)}</td><td>${esc(l.type)}</td><td>${l.consent?'Yes':'No'}</td><td>${new Date(l.date).toLocaleDateString()}</td></tr>`).join(''):'<tr><td colspan="5">No demo leads yet. Open a landing page and test the resource form.</td></tr>'}</tbody></table><div class="actions"><button id="clear">Clear demo leads</button></div></div><div class="notice">These are browser-local test records, not production analytics. Live attribution, delivery, bookings and conversion rates need integrations.</div>`}
$('#content').innerHTML=html;bind();}
function hero(){return `<div class="hero"><div><span class="eyebrow">STRATEGY, MEET MOMENTUM</span><h2>A complete campaign.<br><span>Built around your customer.</span></h2><p>Turn what your business knows into useful content, meaningful connections and a clear next step.</p><button class="lime" data-go="${state.campaign?'Landing pages':'Business brief'}">${state.campaign?'Walk through the journey':'Build your first campaign'} ↗</button></div><div class="rings"><div><div><div>✳</div></div></div></div></div>`}
function field(k,label,type='input',cls=''){return `<label class="${cls}">${label}${type==='textarea'?`<textarea name="${k}" required>${esc(state.brief[k])}</textarea>`:`<input name="${k}" value="${esc(state.brief[k])}" required maxlength="240">`}</label>`}function select(k,label,options){return `<label>${label}<select name="${k}">${options.map(v=>`<option ${state.brief[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function blogBody(i){const b=state.brief,c=state.campaign;return [`Choosing ${c.subject} can feel complicated when every option promises something different. A better starting point is your own situation: what do you need, what matters most and what can you realistically maintain?\n\nStart with the outcome\nBefore comparing products or providers, describe what a good result would look like for you. For ${b.audience}, this may mean balancing convenience, fit and the support available.\n\nThree things to check\n${c.criteria.map((v,j)=>`${j+1}. ${v}: ${c.tips[j]}`).join('\n')}\n\nMake your first decision smaller\nYou do not need to choose everything today. Identify your priority, compare a manageable shortlist and find out what you still need to know.\n\nYour next step\nUse our ${c.tool.toLowerCase()} to turn these questions into a starting direction. Your results are available before you share an email address.`, `Comparing ${c.subject} is easier when you judge each option against the same criteria. This guide gives you a repeatable way to do that.\n\nCreate your comparison criteria\n${c.criteria.map((v,j)=>`${j+1}. ${v} — ${c.tips[j]}`).join('\n')}\n\nSeparate essential from optional\nWrite down three things your choice must deliver. Then list what would be useful but is not essential. This makes trade-offs more visible.\n\nAsk for the missing details\nConfirm what is included, what you would need to do yourself and what ongoing support is available. Record unanswered questions rather than assuming the answer.\n\nTurn the comparison into a plan\nOur ${c.magnet.toLowerCase()} includes a priorities worksheet, comparison table and a next-step checklist. Preview it and save a copy when it is useful to you.`, `Before choosing ${b.offer}, check that the details match your priorities. The right decision depends on your circumstances as well as the offer itself.\n\nWhat do you need it to solve?\nReturn to your main priority. Explain the result you are looking for and ask how the offer would address it.\n\nWhat is included?\nRequest a clear description of scope, cost, timing and any conditions. Add verified details here before publishing this article.\n\nWhat support will you receive?\nAsk how questions are handled and what happens after you take the next step.\n\nWhen might another option fit better?\nCompare the offer against your must-haves. If an essential requirement is not met, ask about an alternative.\n\nReady to explore the fit?\n${b.name} offers ${b.offer}. Review the offer page and send your questions before committing.`][i]}
function head(i){return [`Find your starting point for ${state.campaign.subject}.`,`A useful plan, shaped around you.`,`${state.brief.offer}. Your next step, made clearer.`][i]}
function resourceText(){const c=state.campaign;return `YOUR PRIORITIES\nWhat would a good result look like? ____________________\nYour biggest constraint: ____________________\n\nYOUR STARTING POINT\n${c.criteria.map((v,i)=>`${v}: ${answers[i]||'Add your answer'}`).join('\n')}\n\nTHREE PRACTICAL STEPS\n${c.tips.map((v,i)=>`${i+1}. ${v}`).join('\n')}\n\nCOMPARE YOUR OPTIONS\nOption A: ______  Option B: ______  Option C: ______\nFor each option, record: fit with priorities, full cost, time required, included support and unanswered questions.\n\nBEFORE YOU DECIDE\n□ Confirm the details directly with the provider.\n□ Check the full commitment and conditions.\n□ Choose one achievable next action.\n\nYOUR NEXT ACTION\nI will ____________________ by ____________________.`}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){document.querySelectorAll('[data-demo]').forEach(e=>e.onclick=()=>loadDemo(+e.dataset.demo));document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>go(e.dataset.nav));document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>go(e.dataset.go));document.querySelectorAll('[data-preview]').forEach(e=>e.onclick=()=>{lpStage=+e.dataset.preview;renderLP();$('#preview').showModal()});document.querySelectorAll('[data-blog]').forEach(e=>e.onclick=()=>{blogIndex=+e.dataset.blog;render()});document.querySelectorAll('[data-edit]').forEach(e=>e.oninput=()=>{state.edits[e.dataset.edit]=e.textContent;persist()});if($('#brief'))$('#brief').onsubmit=e=>{e.preventDefault();requestGeneration(e.target)};if($('#sample'))$('#sample').onclick=()=>{state.brief={...defaults};render()};if($('#download'))$('#download').onclick=()=>download('planning-workbook.txt',(state.edits['magnet-title']||state.campaign.magnet)+'\n\n'+personalisedResource());if($('#clear'))$('#clear').onclick=()=>{if(confirm('Delete all demo leads from this browser?')){state.leads=[];persist();render()}}}
function quizChoices(j){if(state.campaign.quizOptions)return state.campaign.quizOptions[j];const t=state.campaign.subject;const sets=t==='indoor plants'?[['Low natural light','Bright indirect light','Direct sunlight'],['A few minutes a week','A regular care routine','I enjoy hands-on care'],['One small surface','A few rooms','A larger space']]:t==='learning options'?[['Explore a new subject','Build practical skills','Work toward a qualification'],['Flexible self-paced learning','Scheduled online classes','In-person learning'],['Independent learning','Occasional feedback','Ongoing guidance']]:t==='workflow tools'?[['Repeated manual entry','Slow handoffs','Limited reporting'],['Just me','A small team','Several teams'],['Standalone tool','A few key integrations','A connected system']]:[['Understand my options','Solve a specific problem','Make a final choice'],['No fixed deadline','Within a few months','As soon as practical'],['I prefer to do it myself','A little guidance helps','I want expert support']];return sets[j]}
function renderLP(){let b=state.brief,c=state.campaign,i=lpStage;$('#landing').innerHTML=`<div class="lp-nav"><strong>${esc(b.name)}</strong><div class="lp-steps">${['Discover','Plan','Act'].map((s,j)=>`<button data-lp="${j}" ${j===i?'class="primary"':''}>${j+1} ${s}</button>`).join('')}</div></div><div class="lp-hero"><span class="eyebrow">${['A LITTLE CLARITY TO GET STARTED','YOUR PERSONALISED RESOURCE','READY WHEN YOU ARE'][i]}</span><h1>${esc(state.edits['lphead'+i]||head(i))}</h1><p>${esc([`Answer three simple questions. Get a starting direction for ${c.subject} with no email required.`,`Get ${c.magnet.toLowerCase()} with practical steps and a comparison worksheet.`,`${b.name}: ${b.description}`][i])}</p></div><div class="lp-body">${i===0?`<form id="quiz" class="lp-form">${c.criteria.map((v,j)=>`<label style="margin-bottom:18px">${j+1}. ${esc(v)}<select name="${j}">${quizChoices(j).map(v=>`<option ${answers[j]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<button class="primary">See my starting direction →</button></form><div id="quiz-result"></div>`:i===1?`<div class="grid">${c.tips.map((v,j)=>`<div class="card"><span class="badge">STEP 0${j+1}</span><p>${esc(v)}</p></div>`).join('')}</div><h2>Preview your workbook</h2><div class="result">${c.criteria.map((v,j)=>`<b>${esc(v)}</b>: ${esc(answers[j]||'Complete the assessment or add your own answer')}<br>`).join('')}<p>Includes a priorities worksheet, comparison table and decision checklist.</p></div><form id="resource-form" class="lp-form"><h3>Get your downloadable workbook</h3><label>Email address<input type="email" name="email" placeholder="you@example.com" required maxlength="254"></label><label style="font-weight:400;margin:18px 0"><input style="display:inline;width:auto;margin:0 7px 0 0" type="checkbox" name="consent">Also send me future tips and offers from ${esc(b.name)}.</label><button class="primary">Get my workbook ↓</button><p class="small">Demo: your email stays in this browser. The workbook downloads here; no email is sent.</p></form><div id="resource-result"></div>`:`<div class="grid"><div class="card"><h3>The offer</h3><p>${esc(b.offer)}</p></div><div class="card"><h3>Who it’s for</h3><p>${esc(b.audience)}</p></div><div class="card"><h3>Choose with clarity</h3><p>Confirm scope, pricing and timing directly before committing.</p></div></div><h2>Your questions, before you decide</h2><details class="card"><summary>What is included and what does it cost?</summary><p>Offer details and pricing have not been supplied. Request the full details using the form below.</p></details><details class="card"><summary>Is this right for my situation?</summary><p>Share your priorities and questions so the business can help you assess the fit.</p></details><form id="enquiry-form" class="lp-form"><h3>${esc(action())}</h3><label>Your email<input name="email" type="email" required placeholder="you@example.com" maxlength="254"></label><label style="margin-top:16px">What would you like help with?<textarea name="message" required maxlength="2000"></textarea></label><button class="primary" style="margin-top:15px">Save demo enquiry →</button><p class="small">Prototype only: this records an enquiry locally. It does not make a booking or contact the business.</p></form><div id="enquiry-result"></div>`}</div><footer>Journey preview · ${esc(b.name)} · <button data-lp="${(i+1)%3}">${['Continue to your plan','Explore the offer','Back to discovery'][i]} →</button><div class="preview-credit">© 2026 Orbit. Developed by <strong>SEO Girl - Ami</strong>. All rights reserved.</div></footer>`;
$('#landing').querySelectorAll('[data-lp]').forEach(e=>e.onclick=()=>{lpStage=+e.dataset.lp;renderLP();$('#preview').scrollTop=0});if($('#quiz'))$('#quiz').onsubmit=e=>{e.preventDefault();answers=Object.fromEntries(new FormData(e.target));$('#quiz-result').innerHTML=`<div class="result"><h3>Your starting direction: Your priorities, brought together</h3><p>${c.criteria.map((v,j)=>esc(v)+': '+esc(answers[j])).join('<br>')}</p><p>${esc(c.tips[0])} ${esc(answers[2]==='I want expert support'?'Ask for help reviewing your options.':'Use a simple comparison before deciding.')}</p><button id="next-plan" class="primary">Build my practical plan →</button></div>`;$('#next-plan').onclick=()=>{lpStage=1;renderLP()}};if($('#resource-form'))$('#resource-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);addLead(f,'Resource');download('my-planning-workbook.txt',(state.edits['magnet-title']||c.magnet)+'\n\n'+personalisedResource());$('#resource-result').innerHTML='<div class="result">Your workbook has downloaded. Your demo request is saved in this browser. No email was sent.</div>';toast('Workbook downloaded. Demo lead saved locally.');};if($('#enquiry-form'))$('#enquiry-form').onsubmit=e=>{e.preventDefault();addLead(new FormData(e.target),'Enquiry');$('#enquiry-result').innerHTML='<div class="result">Your demo enquiry is saved on this device. No message was sent to the business.</div>';e.target.reset()};}
function addLead(f,type){state.leads.push({email:f.get('email'),business:state.brief.name,type,consent:f.get('consent')==='on',message:f.get('message')||'',answers:{...answers},date:new Date().toISOString()});persist()}
$('#close').onclick=()=>$('#preview').close();$('#export').onclick=()=>{if(!state.campaign)return toast('Create a campaign first.');download('orbit-campaign.json',JSON.stringify(state,null,2),'application/json');toast('Campaign exported, including edits and demo records.')};render();
